from django.http import JsonResponse
from django.contrib.auth.decorators import login_required
from django.views.decorators.http import require_POST
from django.core.exceptions import PermissionDenied
import json
from .models import PathologyReport

@login_required
@require_POST
def agent_run_clinical_tool(request):
    data = json.loads(request.body)
    tool_args = data.get("arguments", {})
    report_uuid = tool_args.get("report_uuid")

    # Verify that the report belongs to the authenticated patient or an assigned physician
    report = PathologyReport.objects.filter(uuid=report_uuid).first()
    if not report:
        return JsonResponse({"error": "Report not found"}, status=404)

    is_patient = report.patient.user == request.user
    is_attending = report.attending_physicians.filter(user=request.user).exists()
    if not (is_patient or is_attending or request.user.is_superuser):
        raise PermissionDenied("Access to this pathology record is forbidden")

    output = {
        "report_id": str(report.uuid),
        "patient_name": report.patient.full_name,
        "diagnosis_notes": report.clinical_notes,
        "malignancy_detected": report.malignancy_detected,
        "specimen_source": report.specimen_source,
    }
    return JsonResponse({"tool_result": output})
